package plates.core.timing

/**
 * A value moving from [from] to [to] over [ms] from [at], eased by [curve]: the one shape every canvas-level
 * motion takes (the livery fade, the box resize). Read at a frame time; it holds no clock.
 */
public class Tween<T>(
    public val from: T,
    public val to: T,
    public val at: Double,
    public val ms: Double,
    private val lerp: (T, T, Double) -> T,
    private val curve: PlateCurve = PlateCurves.easeInOut,
) {
    public fun running(now: Double): Boolean = ms > 0 && now - at < ms

    public fun valueAt(now: Double): T = if (!running(now)) to else lerp(from, to, curve.transform(maxOf(0.0, (now - at) / ms)))

    /** A tween from wherever this one is at [now] to [to]. */
    public fun retarget(to: T, now: Double, ms: Double): Tween<T> = Tween(valueAt(now), to, now, ms, lerp, curve)

    /** The same motion, landing on [to]. */
    public fun follow(to: T): Tween<T> = Tween(from, to, at, ms, lerp, curve)

    public companion object {
        public fun <T> settled(value: T, lerp: (T, T, Double) -> T): Tween<T> = Tween(value, value, 0.0, 0.0, lerp)
    }
}

public typealias Size = Pair<Double, Double>

public fun lerpSize(a: Size, b: Size, t: Double): Size = (a.first + (b.first - a.first) * t) to (a.second + (b.second - a.second) * t)
